import {Component, OnInit} from '@angular/core';
import { LoginService } from '../auth/login/login.service';
import { Observable, map } from 'rxjs';

@Component({
  selector: 'app-nav-menu',
  templateUrl: './nav-menu.component.html',
  styleUrls: ['./nav-menu.component.css', '../../styles.css']
})
export class NavMenuComponent implements OnInit {
  loginSuccessMessage: string | null = null;
  isLoggedIn = false;
  isExpanded = false;
  isAdmin$: Observable<boolean>

  constructor(public loginService: LoginService) {
    this.isAdmin$ = this.loginService.getUserRoles().pipe(
      map(roles => roles.includes('Администратор')));
  }

   ngOnInit(): void {
     this.loginService.isLoggedIn().subscribe(isLogged => {
       if (isLogged) {
         this.showLoginSuccess();
       }
     });
   }

  isAdmin(): boolean {
    return this.loginService.hasRole('Администратор');
  }

  toggle() {
    this.isExpanded = !this.isExpanded;
  }

  toggleLanguage() {
    const langToggle = document.getElementById('languageToggle') as HTMLInputElement;
    const isMacedonian = langToggle.checked;
    console.log('Language toggled to:', isMacedonian ? 'Macedonian' : 'English');
  }

  openLoginModal() {
    window.location.href = '/login';
  }

  private showLoginSuccess() {
    this.loginSuccessMessage = 'Logged in successfully!';
    setTimeout(() => {
      this.loginSuccessMessage = null;
    }, 3000);
  }
}
<header>
  <nav class="navbar navbar-expand-lg navbar-dark bg-custom-dark border-bottom">
    <div class="container pisition-relative">
      <a class="navbar-brand d-flex align-items-center" [routerLink]="['/']" routerLinkActive="active-link" [routerLinkActiveOptions]="{ exact: true }">
        <img src="../../assets/smlogo.png" alt="PriceFlow Logo" class="logo">
        <span class="ms-3 text-white fw-bold" style="font-size: 1.6rem; text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.6);">
          PriceFlow
        </span>
      </a>

      <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav">
        <span class="navbar-toggler-icon"></span>
      </button>

      <div class="collapse navbar-collapse" id="navbarNav">
        <ul class="navbar-nav ms-4 me-auto">
          <li class="nav-item" *ngIf="isAdmin()">
            <a class="nav-link text-white fw-bold"
               routerLink="/admin/users"
               routerLinkActive="active-link"
               [routerLinkActiveOptions]="{ exact: true }">Users</a>
          </li>
          <li class="nav-item" *ngIf="isAdmin()">
            <a class="nav-link text-white fw-bold"
               routerLink="/securities"
               routerLinkActive="active-link"
               [routerLinkActiveOptions]="{ exact: true }">Securities</a>
          </li>
        </ul>

        <div class="d-flex align-items-center justify-content-end">
          <div class="language-switch-container">
            <label class="language-switch">
              <input type="checkbox" id="languageToggle" (change)="toggleLanguage()">
              <span class="language-slider"></span>
            </label>
          </div>

          <div *ngIf="!(loginService.isLoggedIn() | async)" class="ogin-button-wrapper d-flex align-items-center position-relative">
            <button (click)="openLoginModal()" class="btn btn-primary ms-3 login">LOGIN</button>

            <div *ngIf="loginSuccessMessage" class="success-toast">
              {{ loginSuccessMessage }}
            </div>
          </div>

          <div *ngIf="(loginService.isLoggedIn() | async)" class="d-flex align-items-center">
            <div class="text-white me-3" style="font-size: 1.2rem; padding: 0.5rem 1rem;">
              Welcome, {{ (loginService.getUsername() | async) || 'User' }}!
            </div>
            <button (click)="loginService.logout();$event.stopPropagation()" class="btn btn-secondary ms-3 login">
              LOGOUT
            </button>
          </div>
        </div>
      </div>
    </div>
  </nav>
</header>
